// 宇树 App WebRTC 通道利用脚本(授权测试)
// 借用 App 已建立的 DataChannel 发送自定义 DDS 请求,并打印所有回包
// 用法: 先在 App 里连接机器人,然后 frida -U -f 或 -n com.unitree.b2dog -l webrtc_harness.js

function sendCmd(topic, api_id, data) {
    Java.perform(function () {
        Java.choose('android.webkit.WebView', {
            onMatch: function (wv) {
                var payload = JSON.stringify({
                    topic: topic, api_id: api_id, id: Math.floor(Math.random() * 100000),
                    data: data, priority: null
                });
                var js = 'appSendCmdToGo2(' + JSON.stringify(payload) + ')';
                console.log('[>>] evaluateJavascript: ' + js);
                wv.post(new Java.registerClass({
                    name: 'com.sec.Run' + Date.now(),
                    implements: [java.lang.Runnable],
                    methods: { run: function () { wv.evaluateJavascript(js, null); } }
                }).$new());
            },
            onComplete: function () {}
        });
    });
}

Java.perform(function () {
    // 打印所有从机器人回来的响应(JS -> native 回调)
    try {
        var JsInterface = Java.use('com.unitree.godog.ui.fragment.web.JsInterface');
