                console.log('[APP>>] sendEvent: ' + event);
                return this.sendEvent(event, act, m, t, s, e2, cb);
            };
        console.log('[*] hooked GlobalWebEventServiceImpl.sendEvent');
    } catch (e) { console.log('[!] hook sendEvent failed: ' + e); }
});

