public static void printPrivateKeyInfo(PrivateKey privateKey) {
    RSAPrivateKey rSAPrivateKey = (RSAPrivateKey) privateKey;
    System.out.println("----------RSAPrivateKey ----------");
    System.out.println("Modulus.length=" + rSAPrivateKey.getModulus().bitLength());
    System.out.println("Modulus=" + rSAPrivateKey.getModulus().toString());
    System.out.println("PrivateExponent.length=" + rSAPrivateKey.getPrivateExponent().bitLength());
    System.out.println("PrivatecExponent=" + rSAPrivateKey.getPrivateExponent().toString());
}

public static String encodeString(String str, String str2) {
    try {
        PublicKey publicKeyLoadPublicKey = loadPublicKey(str2);
        StringBuilder sb = new StringBuilder();
        byte[] bytes = str.getBytes();
        byte[] bArrAdd = null;
        int i = 0;
        while (i < bytes.length) {
            int i2 = i + 100;
            byte[] bArrEncryptData = encryptData(ArrayUtils.subArray(bytes, i, i2), publicKeyLoadPublicKey);
            sb.append(new String(bArrEncryptData));
            bArrAdd = ArrayUtils.add(bArrAdd, bArrEncryptData);
            i = i2;
        }
        return Base64Util.encode(bArrAdd);
    } catch (Exception e) {
        e.printStackTrace();
        return "";
    }
}

